package policy; import core.PortRange;import core.StringUtil; public final class IptablesParser{public FirewallRule parseLine(String line){String clean=StringUtil.stripComment(line).trim();if(clean.isEmpty())return null;String[] t=clean.split("\s+");FirewallRule r=new FirewallRule();for(int i=0;i<t.length;i++){String x=t[i];if((x.equals("-A")||x.equals("-I"))&&i+1<t.length)r.chain(t[++i]);else if((x.equals("-p")||x.equals("--protocol"))&&i+1<t.length)r.protocol(t[++i].toLowerCase());else if((x.equals("-s")||x.equals("--source"))&&i+1<t.length)r.source(t[++i]);else if((x.equals("-d")||x.equals("--destination"))&&i+1<t.length)r.destination(t[++i]);else if((x.equals("--dport")||x.equals("--destination-port"))&&i+1<t.length)r.destinationPort(PortRange.parse(t[++i]));else if((x.equals("--sport")||x.equals("--source-port"))&&i+1<t.length)r.sourcePort(PortRange.parse(t[++i]));else if((x.equals("-j")||x.equals("--jump"))&&i+1<t.length)r.action(t[++i].toUpperCase());else if(x.startsWith("--")&&i+1<t.length)r.attributes().put(x.substring(2),t[++i]);}return r;}}
